const toolKindMeta:Record<ToolKind,[string,string]>={application:["应用程序","APP"],shortcut:["快捷方式","LINK"],script:["脚本","SCRIPT"],link:["网页链接","WEB"],folder:["文件夹","DIR"],system:["系统工具","SYS"]};
function ToolsView(){
 const[tools,setTools]=useState<ToolItem[]>([]),[loaded,setLoaded]=useState(false),[dragging,setDragging]=useState(false),[desktop,setDesktop]=useState(false),[pickerOpen,setPickerOpen]=useState(false),[status,setStatus]=useState("等待拖入工具");
 const toolsRef=useRef<ToolItem[]>([]);
 useEffect(()=>{try{const saved=localStorage.getItem("workbench-tools");if(saved){const parsed=JSON.parse(saved);if(Array.isArray(parsed))setTools(parsed)}}catch{console.warn("Unable to read saved tools")}finally{setLoaded(true)}},[]);
 useEffect(()=>{toolsRef.current=tools},[tools]);
 useEffect(()=>{if(loaded)localStorage.setItem("workbench-tools",JSON.stringify(tools))},[tools,loaded]);
 const addPaths=async(paths:string[])=>{if(!paths.length)return;setStatus("正在检查所选内容...");try{const{invoke}=await import("@tauri-apps/api/core"),result=await invoke<ToolImportResult>("inspect_tool_paths",{paths}),known=new Set(toolsRef.current.map(item=>item.path.toLocaleLowerCase())),accepted:ToolItem[]=[],stamp=Date.now();let duplicates=0;for(const item of result.accepted){const normalized=item.path.toLocaleLowerCase();if(known.has(normalized)){duplicates+=1;continue}known.add(normalized);accepted.push({...item,id:`TOOL-${stamp}-${accepted.length}`})}if(accepted.length)setTools(current=>[...current,...accepted]);const parts=[accepted.length?`已添加 ${accepted.length} 项`:"没有新增工具",duplicates?`${duplicates} 项重复`:"",result.rejected.length?`${result.rejected.length} 项不支持`:""].filter(Boolean);setStatus(parts.join(" / "));}catch(error){setStatus(`添加失败：${String(error)}`)}};
 useEffect(()=>{let disposed=false,unlisten:(()=>void)|undefined;const connect=async()=>{if(!("__TAURI_INTERNALS__" in window)){setStatus("请在 Windows 桌面版中拖入和启动工具");return}setDesktop(true);try{const{getCurrentWebview}=await import("@tauri-apps/api/webview");unlisten=await getCurrentWebview().onDragDropEvent(async event=>{if(disposed)return;const payload=event.payload;if(payload.type==="enter"||payload.type==="over"){setDragging(true);return}if(payload.type==="leave"){setDragging(false);return}setDragging(false);if(payload.type==="drop")await addPaths(payload.paths)})}catch(error){setStatus(`桌面拖放连接失败：${String(error)}`)}};connect();return()=>{disposed=true;unlisten?.()}},[]);
 const pick=async(mode:"files"|"folder")=>{setPickerOpen(false);if(!desktop){setStatus("浏览器预览不能选择本机文件，请使用 Windows 桌面版");return}setStatus(mode==="files"?"正在打开文件选择器...":"正在打开文件夹选择器...");try{const{invoke}=await import("@tauri-apps/api/core"),paths=await invoke<string[]>("pick_tool_paths",{mode});if(paths.length)await addPaths(paths);else setStatus("已取消选择")}catch(error){setStatus(`选择失败：${String(error)}`)}};
 const launch=async(item:ToolItem)=>{if(!desktop){setStatus("浏览器预览不能启动本机程序，请使用 Windows 桌面版");return}setStatus(`正在启动 ${item.name}...`);try{const{invoke}=await import("@tauri-apps/api/core");await invoke("launch_tool",{path:item.path});setStatus(`已启动 ${item.name}`)}catch(error){setStatus(`启动失败：${String(error)}`)}};
 const remove=(id:string)=>setTools(items=>items.filter(item=>item.id!==id));
 return <section className={`operation-module tools-module ${dragging?"dragging":""}`} onClick={()=>{if(pickerOpen)setPickerOpen(false)}}><header><div><b>快捷启动台</b><small>// WINDOWS TOOL LAUNCHER</small></div><span>{String(tools.length).padStart(2,"0")} / TOOLS</span></header><div className="tools-body"><section className="tools-drop"><div className="tools-picker" onClick={event=>event.stopPropagation()}><button className="tools-drop-mark" onClick={()=>{if(!desktop){setStatus("浏览器预览不能选择本机文件，请使用 Windows 桌面版");return}setPickerOpen(value=>!value)}} aria-expanded={pickerOpen} aria-label="添加本机工具" title="选择文件或文件夹"><i/><i/></button>{pickerOpen&&<div className="tools-picker-menu"><button onClick={()=>pick("files")}><b>FILE</b><span>选择文件</span></button><button onClick={()=>pick("folder")}><b>DIR</b><span>选择文件夹</span></button></div>}</div><small>DROP TARGET / LOCAL PATH</small><h2>{dragging?"松开以添加":"拖入常用工具"}</h2><p>支持 EXE、LNK、BAT、CMD、PS1、URL、MSC 和文件夹</p><div className="tools-types">{[["APP","应用"],["LINK","快捷方式"],["SCRIPT","脚本"],["WEB","网页"],["DIR","文件夹"],["SYS","系统工具"]].map(([code,label])=><span key={code}><b>{code}</b>{label}</span>)}</div><footer className={desktop?"online":"offline"}><i/>{desktop?"WINDOWS DESKTOP / READY":"BROWSER PREVIEW / DESKTOP REQUIRED"}</footer></section><section className="tools-library"><header><div><small>LOCAL LIBRARY</small><h2>已添加工具</h2></div><span>{status}</span></header>{tools.length?<div className="tools-grid">{tools.map(item=>{const[label,code]=toolKindMeta[item.kind];return <article key={item.id} className={`tool-card kind-${item.kind}`}><button className="tool-launch" onClick={()=>launch(item)} title={`打开 ${item.path}`}><i aria-hidden="true"><b>{code}</b></i><span><small>{label} / {item.extension||"FOLDER"}</small><strong>{item.name}</strong><em>{item.path}</em></span><b className="tool-open">↗</b></button><button className="tool-remove" onClick={()=>remove(item.id)} title="从工作台移除" aria-label={`从工作台移除 ${item.name}`}>×</button></article>})}</div>:<div className="tools-empty"><b>NO LOCAL TOOL</b><span>将常用程序、快捷方式或文件夹拖到左侧区域</span></div>}</section></div></section>
}
function AddProjectDialog({close,add}:{close:()=>void;add:(title:string,tags:string[])=>void}){
 const[title,setTitle]=useState(""),[tags,setTags]=useState(""),[error,setError]=useState("");
 const titleRef=useRef<HTMLInputElement>(null);
 useEffect(()=>{titleRef.current?.focus();const cancel=(event:KeyboardEvent)=>{if(event.key==="Escape")close()};window.addEventListener("keydown",cancel);return()=>window.removeEventListener("keydown",cancel)},[close]);
 const submit=()=>{const clean=title.trim();if(!clean){setError("请输入项目名称");titleRef.current?.focus();return}add(clean,tags.split(/[,，/]/).map(tag=>tag.trim()).filter(Boolean))};
 return <div className="modal-back project-modal-back" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><div className="add-modal project-modal" role="dialog" aria-modal="true" aria-labelledby="add-project-title"><header><div><small>NEW PROJECT WORKSPACE</small><h2 id="add-project-title">新增项目</h2></div><button onClick={close} aria-label="关闭新增项目">×</button></header><label>PROJECT NAME / 项目名称<input ref={titleRef} value={title} onChange={event=>{setTitle(event.target.value);setError("")}} onKeyDown={event=>{if(event.key==="Enter")submit()}} placeholder="输入项目名称"/></label><label>TAGS / 项目标签<input value={tags} onChange={event=>setTags(event.target.value)} onKeyDown={event=>{if(event.key==="Enter")submit()}} placeholder="例如：产品，设计，开发"/></label><p className={`project-form-error ${error?"show":""}`}>{error||"创建后可设置本机项目目录"}</p><footer><button onClick={close}>取消</button><button className="primary" onClick={submit}>创建项目</button></footer></div></div>
}
function AddPlanDialog({close,add,initialDate=dateKey(new Date())}:{close:()=>void;add:(plan:Omit<PlanItem,"id"|"done">)=>void;initialDate?:string}){
 const now=new Date(),initialTime=`${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
 const[title,setTitle]=useState(""),[date,setDate]=useState(initialDate),[time,setTime]=useState(initialTime),[category,setCategory]=useState("工作"),[customCategory,setCustomCategory]=useState(""),[error,setError]=useState("");
 const titleRef=useRef<HTMLInputElement>(null);
 useEffect(()=>{titleRef.current?.focus();const key=(event:KeyboardEvent)=>{if(event.key==="Escape")close()};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key)},[close]);
 const submit=()=>{const cleanTitle=title.trim(),cleanCategory=(category==="自定义"?customCategory:category).trim();if(!cleanTitle){setError("请输入计划名称");titleRef.current?.focus();return}if(!date){setError("请选择计划日期");return}if(!time){setError("请选择执行时间");return}if(!cleanCategory){setError("请输入计划分类");return}add({title:cleanTitle,date,time,category:cleanCategory})};
 return <div className="modal-back plan-modal-back"><button className="plan-modal-dismiss" aria-label="关闭新增计划" onClick={close}/><div className="add-modal plan-modal" role="dialog" aria-modal="true" aria-labelledby="add-plan-title"><header><div><small>NEW DAILY OPERATION</small><h2 id="add-plan-title">新增计划</h2></div><button onClick={close} aria-label="关闭新增计划">×</button></header><label>PLAN NAME / 计划名称<input ref={titleRef} value={title} onChange={event=>{setTitle(event.target.value);setError("")}} onKeyDown={event=>{if(event.key==="Enter")submit()}} placeholder="输入计划名称"/></label><div className="plan-form-row"><label>DATE / 计划日期<input type="date" value={date} onChange={event=>{setDate(event.target.value);setError("")}}/></label><label>TIME / 执行时间<input type="time" value={time} onChange={event=>{setTime(event.target.value);setError("")}}/></label></div><label>CATEGORY / 计划分类<select value={category} onChange={event=>{setCategory(event.target.value);setError("")}}><option>工作</option><option>项目</option><option>灵感</option><option>自定义</option></select></label>{category==="自定义"&&<label>CUSTOM CATEGORY / 自定义分类<input value={customCategory} onChange={event=>{setCustomCategory(event.target.value);setError("")}} onKeyDown={event=>{if(event.key==="Enter")submit()}} placeholder="输入分类名称"/></label>}<p className={`plan-form-error ${error?"show":""}`} aria-live="polite">{error||"FORM READY"}</p><footer><button onClick={close}>取消</button><button className="primary" onClick={submit}>添加计划</button></footer></div></div>
}
function SearchDrawer({open,close,query,setQuery,items,pick}:{open:boolean;close:()=>void;query:string;setQuery:(s:string)=>void;items:Entry[];pick:(id:string)=>void}){return <aside className={`drawer ${open?"open":""}`}><header><div><small>MEMORY RETRIEVAL</small><h2>灵感检索</h2></div><button onClick={close}>×</button></header><label><span>&gt;</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="输入名称、标签或时间"/></label><p className="result-count">RESULT / {String(items.length).padStart(3,"0")}</p><div className="results">{items.map(e=><button key={e.id} onClick={()=>pick(e.id)}><b>{e.id}</b><span>{e.title}<small>{e.tags.join(" · ")}</small></span><time>{e.createdAt.replaceAll("-",".")}</time></button>)}</div></aside>}
function Settings({prefs,setPrefs,close}:{prefs:Preferences;setPrefs:(p:Preferences)=>void;close:()=>void}){const patch=(x:Partial<Preferences>)=>setPrefs({...prefs,...x});return <div className="settings-back" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><aside className="settings-panel"><header><div><small>SYSTEM CONFIGURATION / 05</small><h2>基础设置</h2></div><button onClick={close}>×</button></header><section><div className="settings-title"><b>GLOBAL</b><span>全局设置</span></div><Toggle label="界面音效" code="SYSTEM AUDIO" value={prefs.sound} change={v=>patch({sound:v})}/><Toggle label="每次显示启动动画" code="BOOT SEQUENCE" value={prefs.boot} change={v=>patch({boot:v})}/><Toggle label="显示系统状态" code="TELEMETRY" value={prefs.showSystem} change={v=>patch({showSystem:v})}/></section><section><div className="settings-title"><b>MEMORY</b><span>灵感模块</span></div><Range label="同屏忆泡上限" value={prefs.density} min={6} max={30} step={1} change={v=>patch({density:v})}/><Range label="漂浮速度" value={prefs.motionSpeed} min={.4} max={1.8} step={.1} change={v=>patch({motionSpeed:v})}/><Toggle label="启用记忆衰减" code="MEMORY AGING" value={prefs.aging} change={v=>patch({aging:v})}/></section><div className="settings-foot"><span>CONFIGURATION SAVED LOCALLY</span><button onClick={()=>setPrefs(defaults)}>RESTORE DEFAULT</button></div></aside></div>}
function Toggle({label,code,value,change}:{label:string;code:string;value:boolean;change:(v:boolean)=>void}){return <div className="setting-row"><div><b>{label}</b><small>{code}</small></div><button className={`toggle ${value?"on":""}`} onClick={()=>change(!value)}><i/><span>{value?"ON":"OFF"}</span></button></div>}
function Range({label,value,min,max,step,change}:{label:string;value:number;min:number;max:number;step:number;change:(v:number)=>void}){return <div className="setting-row range-row"><div><b>{label}</b><small>VALUE / {value}</small></div><input type="range" min={min} max={max} step={step} value={value} onChange={e=>change(Number(e.target.value))}/></div>}
function AddDialog({close,add}:{close:()=>void;add:(a:string,b:string)=>void}){const[t,setT]=useState(""),[s,setS]=useState("");return <div className="modal-back"><div className="add-modal"><small>NEW MEMORY / 快速捕获</small><h2>记录一个新灵感</h2><label>NAME / 名称<input autoFocus value={t} onChange={e=>setT(e.target.value)} /></label><label>SOURCE / 来源链接<input value={s} onChange={e=>setS(e.target.value)}/></label><div><button onClick={close}>CANCEL</button><button className="primary" onClick={()=>add(t,s)}>SAVE MEMORY</button></div></div></div>}
